// PostToolUse hook on `mcp__minsky__session_pr_merge` and
// `mcp__minsky__tasks_status_set` (when result status = DONE): search for
// bridge memories tagged with the completing task's ID, and when candidates
// exist inject an `additionalContext` reminder naming each memory (ID + name)
// with the redundancy-check decision rule.
//
// Originating incident: 2026-05-23 mt#2056 closeout. Bridge memory `70ba7f79`
// had a budget criterion with no retirement mechanism — no actor, no trigger,
// nothing to execute the retirement. Three rounds of user pushing to reach the
// correct action (delete). The retrospective identified "half-measure
// defaulting under uncertainty" as the cognitive pattern; this hook is the
// structural fix that makes the retirement decision unavoidable at the right
// moment.
//
// Architecture: same shape as `.claude/hooks/drive-pr-to-convergence.ts`
// (PostToolUse, inject additionalContext on success, always exit 0,
// informational only). Uses `readInput()`, `writeOutput()`, and
// `execWithPath()` from `./types.ts`.
//
// Override env var: MINSKY_SKIP_BRIDGE_RETIREMENT — when set to 1/true/yes,
// suppress the context injection and audit-log to stdout.
//
// Cross-references:
// - Memory `76153081` — bridge memory retirement decision rule (behavioral
//   bridge until this hook shipped)
// - `.claude/hooks/drive-pr-to-convergence.ts` — architectural precedent
// - `.claude/hooks/memory-search.ts` — pattern for minsky CLI invocation
// - CLAUDE.md §Temporary mechanism budget — parent rule
// - mt#2056 — originating task
// - mt#2062 — this hook's tracking task
// @see mt#2062

import { execWithPath, readInput, writeOutput } from "./types";
import type { ToolHookInput, HookOutput, ExecResult } from "./types";

/** Override env var name (source of truth — used in tests and CLAUDE.md docs). */
export const OVERRIDE_ENV_VAR = "MINSKY_SKIP_BRIDGE_RETIREMENT";

/** Tool names this hook reacts to. */
const TARGET_TOOLS = new Set(["mcp__minsky__session_pr_merge", "mcp__minsky__tasks_status_set"]);

/**
 * Timeout for the `minsky memory list` subprocess call (ms).
 * The hook's host cap is 10s (settings.json). We use 7s (70%) leaving
 * headroom for process startup, stdout writes, and OS scheduling jitter.
 */
const LOOKUP_TIMEOUT_MS = 7_000;

/**
 * The ADR-012 association type meaning "this memory tracks that task's
 * completion" — the exact relationship this hook looks up at DONE time.
 * The vocabulary was closed in code by mt#4448; before that the column
 * accepted any string, which is why a body-text search was ever needed.
 */
const TRACKS_TASK_ASSOCIATION = "tracksTask";

// ---------------------------------------------------------------------------
// Tool input / result parsing
// ---------------------------------------------------------------------------

/**
 * Extract the task ID from the tool input, depending on which tool fired.
 *
 * - `session_pr_merge`: uses `tool_input.task` or `tool_input.taskId`
 * - `tasks_status_set`: uses `tool_input.taskId`
 *
 * Returns null if the task ID cannot be determined.
 */
export function extractTaskId(input: ToolHookInput): string | null {
  const toolInput = input.tool_input;
  if (!toolInput || typeof toolInput !== "object") return null;

  // Both tools accept taskId; session_pr_merge additionally accepts `task`
  const taskId =
    typeof toolInput["taskId"] === "string"
      ? toolInput["taskId"]
      : typeof toolInput["task"] === "string"
        ? toolInput["task"]
        : null;

  return taskId;
}

/**
 * Determine whether the tool result indicates a DONE status transition.
 *
 * For `session_pr_merge`: merge succeeds → task transitions to DONE atomically.
 * We fire whenever `success === true`.
 *
 * For `tasks_status_set`: fire only when the resulting status is "DONE".
 * Check `tool_result.status` or `tool_result.task.status` depending on the
 * response shape.
 */
export function isDoneTransition(input: ToolHookInput): boolean {
  const toolName = input.tool_name;
  const result = input.tool_result;

  if (!result || typeof result !== "object") return false;

  if (toolName === "mcp__minsky__session_pr_merge") {
    // Merge success = DONE transition (at-merge handler sets DONE atomically)
    return result["success"] === true;
  }

  if (toolName === "mcp__minsky__tasks_status_set") {
    // Must be successful AND the resulting status must be DONE
    if (result["success"] !== true) return false;
    // Response may carry the new status in different shapes
    const status =
      typeof result["status"] === "string"
        ? result["status"]
        : typeof result["task"] === "object" &&
            result["task"] !== null &&
            typeof (result["task"] as Record<string, unknown>)["status"] === "string"
          ? (result["task"] as Record<string, unknown>)["status"]
          : null;
    return status === "DONE";
  }

  return false;
}

// ---------------------------------------------------------------------------
// Memory search and bridge-candidate filtering
// ---------------------------------------------------------------------------

/**
 * Minimal memory record shape from `minsky memory list`.
 * Only the fields needed for bridge-candidate detection and the reminder.
 */
export interface MemoryRecordLite {
  id: string;
  name: string;
  description: string;
  content: string;
  tags?: string[];
}

export interface MemoryListResponse {
  records: MemoryRecordLite[];
}

/**
 * Outcome of a candidate lookup.
 *
 * The two failure-free outcomes must stay distinguishable: a lookup that ran
 * and found nothing is NOT the same as a lookup that never ran. Collapsing
 * them into one `null` is what let this hook report "nothing to retire" for
 * its entire life while its subprocess was exiting 1 (mt#4449).
 */
export type CandidateLookup =
  | { ok: true; candidates: MemoryRecordLite[] }
  | { ok: false; reason: string };

/**
 * Parse the JSON output from `minsky memory list`.
 *
 * The CLI emits JSON on stdout BY DEFAULT. There is no `--output` flag on
 * this command — or on any other, outside `tasks deps --output <file>` — and
 * passing one makes the process exit 1 with `unknown option '--output'`
 * before it does any work (mt#4449).
 *
 * Returns null on parse failure or unexpected shape, so the caller can report
 * a lookup FAILURE rather than an empty result. Defensively validates the
 * record array and drops entries that don't conform.
 */
export function parseListOutput(stdout: string): MemoryListResponse | null {
  const trimmed = stdout.trim();
  if (!trimmed) return null;

  let parsed: unknown;
  try {
    parsed = JSON.parse(trimmed);
  } catch {
    // Fallback: scan for a JSON object start (handles warning lines before output)
    const lines = trimmed.split("\n");
    const candidateStarts: number[] = [];
    for (let i = 0; i < lines.length; i++) {
      if ((lines[i] ?? "").trimStart().startsWith("{")) {
        candidateStarts.push(i);
      }
    }
    let fallback: unknown = null;
    for (let i = candidateStarts.length - 1; i >= 0; i--) {
      try {
        fallback = JSON.parse(lines.slice(candidateStarts[i]).join("\n"));
        break;
      } catch {
        // Try earlier candidate
      }
    }
    if (fallback === null) return null;
    parsed = fallback;
  }

  if (!parsed || typeof parsed !== "object") return null;
  const obj = parsed as Record<string, unknown>;

  // `memory list` returns records directly; `memory search` wrapped each in
  // `{ record, score }`. Unwrapping is the shape difference between them.
  const rawRecords = Array.isArray(obj["records"]) ? (obj["records"] as unknown[]) : [];

  const records: MemoryRecordLite[] = [];
  for (const item of rawRecords) {
    if (!item || typeof item !== "object") continue;
    const record = item as Record<string, unknown>;
    if (typeof record["id"] !== "string" || typeof record["name"] !== "string") continue;
    const tags = Array.isArray(record["tags"])
      ? (record["tags"] as unknown[]).filter((t): t is string => typeof t === "string")
      : undefined;
    records.push({
      id: record["id"],
      name: record["name"],
      description: typeof record["description"] === "string" ? record["description"] : "",
      content: typeof record["content"] === "string" ? record["content"] : "",
      tags,
    });
  }

  return { records };
}

/**
 * Determine whether a memory record is bridge-shaped.
 *
 * A memory is a bridge candidate when ANY of:
 * - its `tags` array contains `"bridge-memory"`
 * - its `description` contains the word "bridge" (case-insensitive)
 * - its `content` contains the phrase "Tracking task" (case-insensitive)
 * - its `description` or `content` contains "bridge" (case-insensitive) and
 *   the task ID
 *
 * The last condition catches bridge memories that mention the task ID even
 * when they weren't explicitly tagged.
 */
export function isBridgeCandidate(record: MemoryRecordLite, taskId: string): boolean {
  // Tag check
  if (record.tags && record.tags.includes("bridge-memory")) return true;

  const descLower = record.description.toLowerCase();
  const contentLower = record.content.toLowerCase();
  const taskIdLower = taskId.toLowerCase();

  // "bridge" in description or content
  if (descLower.includes("bridge") || contentLower.includes("bridge")) return true;

  // "Tracking task" phrase (common bridge memory marker)
  if (descLower.includes("tracking task") || contentLower.includes("tracking task")) return true;

  // Task ID mentioned (belt-and-suspenders: catch task-ID-tagged memories)
  if (descLower.includes(taskIdLower) || contentLower.includes(taskIdLower)) return true;

  return false;
}

/**
 * Look up bridge-shaped candidates for a task by EXACT association.
 *
 * `associations.tracksTask` is an indexed JSONB containment match, so a task
 * id either is in the association or is not — the question an identifier
 * actually asks. This replaced a `minsky memory search <taskId>`, which was
 * wrong on two independent counts (mt#4449):
 *
 *  1. It passed `--output json`, which is not a valid flag, so the subprocess
 *     exited 1 and this function returned "no candidates" on EVERY call.
 *  2. Even had it parsed, `memory search` is embedding-ranked. An identifier's
 *     meaning is not its spelling, so it returns a full, plausible set of
 *     semantic neighbours that need not contain the exact match. Measured
 *     2026-08-25: searching `mt#4494` returned 10 records at near-identical
 *     distances (1.1795-1.1852) and did NOT include the one memory whose
 *     `tracksTask` names it. The exact lookup returns that record and only it.
 *
 * A further property worth keeping: this path does not touch the embedding
 * provider, so it still answers when embeddings are degraded — the state the
 * old call could not distinguish from "nothing to retire".
 *
 * Fail-open is preserved (the caller emits nothing on `ok: false`), but the
 * REASON is now carried out rather than flattened into a null.
 */
export function lookupBridgeCandidates(
  taskId: string,
  timeoutMs: number = LOOKUP_TIMEOUT_MS,
  // Injected rather than reached for, so the argv this builds can be asserted
  // directly. The defect being fixed here WAS the argv — a test that has to
  // patch a module import to see it would not have caught the flag that made
  // the subprocess exit 1.
  exec: (cmd: string[], options?: { timeout?: number }) => ExecResult = execWithPath
): CandidateLookup {
  // No `--limit`: the association filter is already exact, so the result set
  // is the candidates themselves rather than a ranked prefix of the corpus.
  // (`memory list` defaults to 500 and reports `truncated: true` when it caps
  // — a limit here would silently re-introduce a ranked-prefix read.)
  //
  // `--all-projects` IS passed, and the reason is measured rather than
  // assumed. ADR-021 project scoping excludes `scope: "user"` memories, and
  // 49 of the 168 memories carrying `tracksTask` are user-scoped — 29% of the
  // corpus this hook exists to find. Concretely, mt#1034 has 7 tracking
  // memories and the scoped query returns 0 of them. A memory that tracks
  // `mt#1034` is about THIS project whatever bucket it sits in: the task id
  // is already the scope, so project scoping adds no precision and costs
  // recall. All figures measured 2026-08-25 against the full corpus (1239
  // records, untruncated).
  const result = exec(
    [
      "minsky",
      "memory",
      "list",
      "--association-type",
      TRACKS_TASK_ASSOCIATION,
      "--association-target",
      taskId,
      "--all-projects",
    ],
    { timeout: timeoutMs }
  );

  if (result.timedOut) {
    return { ok: false, reason: `lookup timed out after ${timeoutMs}ms` };
  }
  if (result.exitCode !== 0) {
    const detail = (result.stderr ?? "").trim().split("\n")[0] ?? "";
    return {
      ok: false,
      reason: `\`minsky memory list\` exited ${result.exitCode}${detail ? `: ${detail}` : ""}`,
    };
  }

  const parsed = parseListOutput(result.stdout);
  if (!parsed) {
    return { ok: false, reason: "could not parse `minsky memory list` output as JSON" };
  }

  return {
    ok: true,
    candidates: parsed.records.filter((record) => isBridgeCandidate(record, taskId)),
  };
}

// ---------------------------------------------------------------------------
// Reminder construction
// ---------------------------------------------------------------------------

/**
 * Build the additionalContext reminder when bridge candidates exist.
 * Names each candidate (ID + name) so the agent has a concrete list to act on.
 */
export function buildReminder(taskId: string, candidates: MemoryRecordLite[]): string {
  const candidateList = candidates.map((c) => `  - \`${c.id}\` — ${c.name}`).join("\n");

  return [
    `Task ${taskId} has just transitioned to DONE.`,
    "",
    `**Bridge-memory retirement check (required):**`,
    `The following bridge-shaped memories were found for task ${taskId}:`,
    "",
    candidateList,
    "",
    "**Decision rule for each candidate:**",
    "1. Compare the memory's content against the task spec and merged PR.",
    "2. If the memory's content is **redundant** with the spec + PR",
    "   (i.e., a reader can find the same information there) →",
    "   **delete via `mcp__minsky__memory_delete`**.",
    "3. If the memory contains **independent value** not captured in the",
    "   spec or PR (e.g., a process lesson, a re-usable rule, a cross-task",
    "   pattern) → **update via `mcp__minsky__memory_update`** to remove the",
    "   bridge framing (remove `bridge-memory` tag, rewrite the description",
    '   as a standing rule rather than a "until X ships" interim).',
    "",
    "A non-empty candidate list always requires an explicit decision per",
    'rule (2) or (3) above — not a deferred "I\'ll check later".',
  ].join("\n");
}

// ---------------------------------------------------------------------------
// Main decision function
// ---------------------------------------------------------------------------

/**
 * Main decision function. Performs the candidate lookup and returns the
 * context string to inject, or null if the hook should emit nothing.
 *
 * Paths that emit no context: non-matching tool, failed result, not a DONE
 * transition, override env var set, lookup failure, or no bridge candidates
 * found. Only the last of those is genuinely silent — an override and a
 * lookup failure both log to stderr, so the two states that used to be
 * indistinguishable now report differently. Nothing on any path writes to
 * stdout except `writeOutput`'s single JSON object.
 *
 * Exported for testability with injectable deps.
 */
export function decide(
  input: ToolHookInput,
  lookupFn: (taskId: string) => CandidateLookup = lookupBridgeCandidates
): string | null {
  // Non-matching tool: silent.
  if (!TARGET_TOOLS.has(input.tool_name)) return null;

  // Override env var: suppress with audit log.
  const override = process.env[OVERRIDE_ENV_VAR];
  if (override === "1" || override === "true" || override === "yes") {
    // stderr, not stdout. `types.ts` states the contract: "Claude Code
    // discards a hook's ENTIRE output when stdout carries anything besides
    // the single JSON object, which silently voids even a different guard's
    // `deny`" (mt#3625). This branch returns null so it emits no JSON of its
    // own, but a bare line on stdout is a hazard regardless, and it was the
    // one path in this file still inconsistent with that rule.
    process.stderr.write(
      `[bridge-memory-retirement] override active (${OVERRIDE_ENV_VAR}=${override}) — skipping\n`
    );
    return null;
  }

  // Not a DONE transition: silent.
  if (!isDoneTransition(input)) return null;

  // Extract task ID for the search.
  const taskId = extractTaskId(input);
  if (!taskId) return null;

  // Look up bridge candidates. Fail-open is preserved — a failed lookup still
  // emits no retirement check and never blocks the tool call — but it is no
  // longer SILENT, because "the lookup broke" and "there is nothing to retire"
  // produced identical output for this hook's entire life (mt#4449).
  //
  // Diagnostics go to stderr, not stdout: stdout carries the HookOutput JSON
  // protocol, and a bare log line there is only safe on paths that emit no
  // JSON. stderr is safe on every path.
  const lookup = lookupFn(taskId);
  if (!lookup.ok) {
    process.stderr.write(
      `[bridge-memory-retirement] candidate lookup FAILED for ${taskId} — ${lookup.reason}. ` +
        `No retirement check emitted; this is not the same as "no candidates found".\n`
    );
    return null;
  }
  if (lookup.candidates.length === 0) return null;

  return buildReminder(taskId, lookup.candidates);
}

// ---------------------------------------------------------------------------
// Entry point
// ---------------------------------------------------------------------------

/**
 * Main entrypoint. Reads ToolHookInput from stdin; emits HookOutput JSON to
 * stdout when bridge candidates exist. Always exits 0 — the hook is
 * informational and must never block the tool call's success surfacing.
 */
async function main(): Promise<void> {
  let input: ToolHookInput;
  try {
    input = await readInput<ToolHookInput>();
  } catch {
    // Malformed stdin — exit silently. Never block.
    process.exit(0);
  }

  const reminder = decide(input);
  if (reminder === null) {
    process.exit(0);
  }

  const output: HookOutput = {
    hookSpecificOutput: {
      hookEventName: "PostToolUse",
      additionalContext: reminder,
    },
  };
  writeOutput(output);
  process.exit(0);
}

if (import.meta.main) {
  main();
}
